const AclSchema = z
  .strictObject({
    acl_name: z.string().regex(/^[^\s]+$/),
    criterion: z.string().regex(/^[^\s]+$/),
    metadata: z.record(z.string(), z.looseObject({})).exactOptional(),
    value: z.string().exactOptional(),
  })
  .openapi({
    description:
      'The use of Access Control Lists (ACL) provides a flexible solution to perform\ncontent switching and generally to take decisions based on content extracted\nfrom the request, the response or any environmental status.\n',
    required: ['acl_name', 'criterion'],
    title: 'ACL Lines',
    'x-go-type': 'models.ACL',
    'x-go-type-import': { path: 'github.com/haproxytech/client-native/v6/models' },
  })
  .openapi('Acl')

