const AcmeProviderSchema = z
  .strictObject({
    account_key: z
      .string()
      .exactOptional()
      .openapi({ description: 'Path where the the ACME account key is stored' }),
    acme_provider: z
      .string()
      .exactOptional()
      .openapi({ description: 'DNS provider for the dns-01 challenge' }),
    acme_vars: z
      .record(z.string(), z.string())
      .exactOptional()
      .openapi({
        description: 'List of variables passed to the dns-01 provider (typically API keys)',
      }),
    bits: z
      .int()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Number of bits used when generating an RSA certificate. Ignored when keytype is ECDSA (curves is used instead).',
        'x-omitempty': true,
      }),
    challenge: z
      .enum(['http-01', 'dns-01', 'dns-persist-01'])
      .exactOptional()
      .openapi({ description: 'ACME challenge type.' }),
    challenge_ready: z
      .array(z.enum(['cli', 'dns', 'none']))
      .min(1)
      .max(2)
      .superRefine((items, ctx) => {
        const seen = new Map()
        for (const [i, val] of items.entries()) {
          const key = JSON.stringify(val)
          if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
          else seen.set(key, i)
        }
      })
      .exactOptional()
      .openapi({
        description:
          'How to wait for the DNS propagation: either wait for a CLI event on\nthe runtime socket (useful with dataplaneapi), or let HAProxy query\nthe DNS TXT record by itself using the default resolvers, or both,\nor none at all.\n',
        'x-omitempty': true,
      }),
    contact: z
      .string()
      .exactOptional()
      .openapi({ description: 'Contact email for the ACME account' }),
    curves: z
      .string()
      .exactOptional()
      .openapi({ description: 'Curves used with the ECDSA key type' }),
    directory: z
      .string()
      .regex(/^https:\/\/[^\s]+$/)
      .openapi({
        description:
          "URL to the ACME provider's directory. For example:\nhttps://acme-staging-v02.api.letsencrypt.org/directory\n",
      }),
    dns_delay: z
      .int()
      .nullable()
      .exactOptional()
      .openapi({
        description: 'Delay before the first DNS resolution attempt and between retries.',
        'x-default-unit': 's',
        'x-duration': true,
      }),
    dns_timeout: z
      .int()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          "Timeout before DNS propagation check fails when using 'dns' in 'challenge_ready'.",
        'x-default-unit': 's',
        'x-duration': true,
      }),
    eab_key_id: z
      .string()
      .exactOptional()
      .openapi({ description: 'Path where the EAB key id is stored' }),
    eab_mac_alg: z
      .enum(['HS256', 'HS384', 'HS512'])
      .exactOptional()
      .openapi({ description: 'MAC algorithm used for EAB signing' }),
    eab_mac_key: z
      .string()
      .exactOptional()
      .openapi({ description: 'Path where the EAB MAC key is stored' }),
    keytype: z
      .enum(['RSA', 'ECDSA'])
      .exactOptional()
      .openapi({ description: 'Type of key to generate' }),
    map: z
      .string()
      .exactOptional()
      .openapi({
        description: 'The map which will be used to store the ACME token (key) and thumbprint',
      }),
    metadata: z.record(z.string(), z.looseObject({})).exactOptional(),
    name: z.string().openapi({ description: "ACME provider's name" }),
    profile: z
      .string()
      .exactOptional()
      .openapi({
        description:
          "Request a specific certificate profile from the CA by including a 'profile'\nfield in the newOrder request (draft-ietf-acme-profiles). Profile names\nare CA-specific short identifiers (e.g. 'classic', 'shortlived').\n",
      }),
    reuse_key: z
      .enum(['enabled', 'disabled'])
      .exactOptional()
      .openapi({ description: 'Try to reuse the private key instead of generating a new one.' }),
  })
  .openapi({
    description: 'Define an ACME provider to generate certificates automatically',
    required: ['name', 'directory'],
    title: 'ACME Provider',
    'x-go-type': 'models.AcmeProvider',
    'x-go-type-import': { path: 'github.com/haproxytech/client-native/v6/models' },
  })
  .openapi('AcmeProvider')

