export const postServicesHaproxyConfigurationAcmeRoute = createRoute({
  method: 'post',
  path: '/services/haproxy/configuration/acme',
  tags: ['Acme'],
  summary: 'Add an ACME provider',
  description: 'Adds a new ACME provider to the configuration file.',
  operationId: 'createAcmeProvider',
  request: {
    query: z.object({
      transaction_id: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'ID of the transaction where we want to add the operation. Cannot be used when version is specified.',
            in: 'query',
            name: 'transaction_id',
            schema: { type: 'string' },
            required: false,
          },
        }),
      version: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              'Version used for checking configuration version. Cannot be used when transaction is specified, transaction has its own version.',
            in: 'query',
            name: 'version',
            schema: { type: 'integer' },
            required: false,
          },
        }),
      force_reload: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            description:
              'If set, do a force reload, do not wait for the configured reload-delay. Cannot be used when transaction is specified, as changes in transaction are not applied directly to configuration.',
            in: 'query',
            name: 'force_reload',
            schema: { default: false, type: 'boolean' },
            required: false,
          },
        }),
    }),
    body: { content: { 'application/json': { schema: AcmeProviderSchema } }, required: true },
  },
  responses: {
    201: {
      description: 'ACME provider created',
      content: { 'application/json': { schema: AcmeProviderSchema } },
    },
    202: {
      description: 'Configuration change accepted and reload requested',
      content: { 'application/json': { schema: AcmeProviderSchema } },
      headers: z.object({
        'Reload-ID': z
          .string()
          .exactOptional()
          .openapi({ description: 'ID of the requested reload', param: { required: false } }),
      }),
    },
    400: BadRequestResponse,
    409: AlreadyExistsResponse,
    default: DefaultErrorResponse,
  },
})

