export const postServicesHaproxyTransactionsRoute = createRoute({
  method: 'post',
  path: '/services/haproxy/transactions',
  tags: ['Transactions'],
  summary: 'Start a new transaction',
  description: "Starts a new transaction and returns it's id",
  operationId: 'startTransaction',
  request: {
    query: z.object({
      version: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .openapi({
          param: {
            description: 'Configuration version on which to work on',
            in: 'query',
            name: 'version',
            required: true,
            schema: { type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    201: {
      description: 'Transaction started',
      content: { 'application/json': { schema: TransactionSchema } },
      headers: z.object({
        'Configuration-Version': z
          .string()
          .exactOptional()
          .openapi({ description: 'Configuration file version', param: { required: false } }),
      }),
    },
    429: TooManyRequestsResponse,
    default: DefaultErrorResponse,
  },
})

