export const putServicesHaproxyTransactionsIdRoute = createRoute({
  method: 'put',
  path: '/services/haproxy/transactions/{id}',
  tags: ['Transactions'],
  summary: 'Commit transaction',
  description: 'Commit transaction, execute all operations in transaction and return msg',
  operationId: 'commitTransaction',
  request: {
    params: z.object({
      id: z
        .string()
        .openapi({
          param: {
            description: 'Transaction id',
            in: 'path',
            name: 'id',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      force_reload: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            description:
              'If set, do a force reload, do not wait for the configured reload-delay. Cannot be used when transaction is specified, as changes in transaction are not applied directly to configuration.',
            in: 'query',
            name: 'force_reload',
            schema: { default: false, type: 'boolean' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Transaction successfully committed',
      content: { 'application/json': { schema: TransactionSchema } },
      headers: z.object({
        'Configuration-Version': z
          .string()
          .exactOptional()
          .openapi({ description: 'Configuration file version', param: { required: false } }),
      }),
    },
    202: {
      description: 'Configuration change accepted and reload requested',
      content: { 'application/json': { schema: TransactionSchema } },
      headers: z.object({
        'Configuration-Version': z
          .string()
          .exactOptional()
          .openapi({ description: 'Configuration file version', param: { required: false } }),
        'Reload-ID': z
          .string()
          .exactOptional()
          .openapi({ description: 'ID of the requested reload', param: { required: false } }),
      }),
    },
    400: BadRequestResponse,
    404: NotFoundResponse,
    406: NotAcceptableResponse,
    default: DefaultErrorResponse,
  },
})

